pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {ACCURAL_DEPOSIT} from "../src/ACCURAL_DEPOSIT.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    ACCURAL_DEPOSIT c;

    function setUp() public {
        c = new ACCURAL_DEPOSIT();
    }

    function _test(uint256 a, uint256 b) internal {
        try c.SetMinSum(a) {} catch { return; }
        try c.SetMinSum(b) {} catch { return; }
        assertTrue(c.MinSum() == b);
    }

    function testFuzz_test(uint256 a, uint256 b) public {
        _test(a, b);
    }

    receive() external payable {}
}
